INSERT INTO `hotels` VALUES (3,'New Tribeni Guest House','Gongabu','Kathmandu',NULL,'Nepal',NULL,'r47327468@gmail.com','Welcome we are located at Samakhusi and have a great time here','2026-01-11 14:23:00','2026-03-26 12:39:06','[\"data:image/jpeg;base64,\",\"data:image/jpeg;base64,\",\"data:image/jpeg;base64,\",\"data:image/jpeg;base64,\",\"data:image/jpeg;base64,\",\"data:image/jpeg;base64,\",\"data:image/jpeg;base64,\",\"data:image/jpeg;base64,\",\"data:image/jpeg;base64,\",\"data:image/jpeg;base64,\",\"data:image/jpeg;base64,\",\"data:image/jpeg;base64,\",\"data:image/jpeg;base64,\",\"data:image/jpeg;base64,\",\"data:image/jpeg;base64,\",\"data:image/jpeg;base64,\",\"data:image/jpeg;base64,\",\"data:image/jpeg;base64,\"]',5.00,28.73194550,86.31201600,'verified',NULL,-740.00);
INSERT INTO `hotels` VALUES (5,'Majestic Lake Front','Street 18B, Lakeside Rd','Pokhara','','Nepal','9880139821','musg9618@gmail.com','Comfortable Accommodations: Majestic Lake Front Hotel & Suites in Pokhara offers family rooms with air-conditioning, private bathrooms, balconies, and garden or lake views. Each room includes a mini-bar, TV, and free WiFi.\n\nWellness and Leisure: Guests can relax at the spa and wellness center, sun terrace, or year-round outdoor swimming pool. The hotel features a fitness center, sauna, and outdoor fireplace.\n\nDining Experience: The family-friendly restaurant serves Chinese, British, Indian, and Nepalese cuisines, alongside international and European dishes. Breakfast options include continental, American, and Asian.\n\nPrime Location: Located 2.5 mi from Pokhara Airport, the hotel is a 13-minute walk from Pokhara Lakeside. Nearby attractions include Fewa Lake and Tal Barahi Temple.','2026-03-13 15:04:37','2026-03-26 14:19:31','[\"data:image/jpeg;base64,\",\"data:image/jpeg;base64,\",\"data:image/jpeg;base64,\",\"data:image/jpeg;base64,\",\"data:image/jpeg;base64,\",\"data:image/jpeg;base64,\",\"data:image/jpeg;base64,\",\"data:image/jpeg;base64,\"]',5.00,28.19981765,84.00146484,'verified',15,0.00);
